package com.example.complaintmanagement.repository; import com.example.complaintmanagement.entity.*; import org.springframework.data.jpa.repository.*; import java.util.*; public interface ComplaintRepository extends JpaRepository<Complaint,Long>{ Optional<Complaint> findByComplaintNumber(String n); List<Complaint> findByCreatedByIdOrderByCreatedAtDesc(Long id); List<Complaint> findByAssignedToIdOrderByCreatedAtDesc(Long id); long countByStatus(ComplaintStatus s); long countByPriority(Priority p); long countByCreatedById(Long id); List<Complaint> findTop10ByOrderByCreatedAtDesc(); @Query("select c from Complaint c where (:q is null or lower(c.complaintNumber) like lower(concat('%',:q,'%')) or lower(c.title) like lower(concat('%',:q,'%')) or lower(c.createdBy.username) like lower(concat('%',:q,'%'))) and (:status is null or c.status=:status) and (:priority is null or c.priority=:priority) and (:categoryId is null or c.category.id=:categoryId) order by c.createdAt desc") List<Complaint> search(@org.springframework.data.repository.query.Param("q") String q,@org.springframework.data.repository.query.Param("status") ComplaintStatus status,@org.springframework.data.repository.query.Param("priority") Priority priority,@org.springframework.data.repository.query.Param("categoryId") Long categoryId); }